/**
 * Storybook-only localized strings.
 * These are NOT included in the production bundle.
 *
 * @internal This module is for Storybook documentation only.
 */
export interface IStorybookStrings {
    currentValue: string;
    selected: string;
    applied: string;
    none: string;
    noSelectionYet: string;
}
/**
 * Get storybook-specific localized strings based on the current locale.
 * Falls back to English if the locale is not found.
 *
 * @internal
 * @param locale - The current i18n locale (e.g., 'en-US', 'es-MX', 'fr-CA')
 * @returns Localized storybook strings
 *
 * @example
 * ```tsx
 * const { locale } = useDatePickerTranslations();
 * const storybook = getStorybookStrings(locale);
 * <p>{storybook.selected} {date.toLocaleDateString()}</p>
 * ```
 */
export declare function getStorybookStrings(locale: string): IStorybookStrings;
